[496, 2032, "2031-32", 2300000000, "£2.3 billion", null, "para 3.16 (p.69)", "The Budget includes several changes to corporation and bank taxes, which increase receipts by £2.3 billion in 2031-32."],
[497, 2032, "2031-32", 1000000000, "£1 billion", null, "para 3.16 (p.69)", "This is estimated to raise an average of £1 billion per year from 2027-28."],
[498, 2028, "2027-28", 1500000000, "£1.5 billion", null, "para 3.16 (p.69)", "Over the 15 months this is in effect, it is estimated to yield a total of £1.5 billion."],
[499, 2028, "2027-28", 190000000, "£190 million", null, "para 3.16 (p.69)", "This is net of an estimated £190 million reduction in receipts as some banks are assumed to move profits out of the UK in response to the higher tax rate."],
[500, 2030, "2029-30", 700000000, "£0.7 billion", null, "para 3.16 (p.69)", "Restricting sovereign wealth and overseas public pension funds’ immunity from direct taxes on UK income and gains from January 2029 raises £0.7 billion by 2029-30."],
[501, 2032, "2031-32", 1000000000, "£1.0 billion", null, "para 3.17 (p.69)", "Together, the measures announced at this Budget are estimated to raise £1.0 billion by 2031-32:"],
[502, 2032, "2031-32", 600000000, "£0.6 billion", null, "para 3.17 (p.69)", "The additional 2 percentage point increase in all rates of saving income tax is estimated to yield £0.6 billion a year on average from 2028-29."],
[503, 2032, "2031-32", 200000000, "£0.2 billion", null, "para 3.17 (p.69)", "A behavioural response, primarily reflecting additional usage of other tax advantaged assets, such as Individual Savings Accounts, reduces the yield by around £0.2 billion a year."],
[504, 2032, "2031-32", 400000000, "£0.4 billion", null, "para 3.17 (p.69)", "The further 2 percentage point increase in all rates of property income tax is estimated to raise £0.4 billion a year on average from 2028-29."],
[505, 2032, "2031-32", 100000000, "£0.1 billion", null, "para 3.17 (p.69)", "The costing of this policy includes small behavioural responses, reflecting additional tax-motivated incorporation and higher non-compliance, that reduce the yield by £0.1 billion a year."],
[506, 2030, "2029-30", 800000000, "£0.8 billion", null, "para 3.18 (p.70)", "Changes to the taxation framework for distributions from companies to individuals from April 2028 which is estimated to raise £0.8 billion by 2029-30."],
[507, 2030, "2029-30", 300000000, "£0.3 billion", null, "para 3.18 (p.70)", "A reduction to the lifetime limit for the business asset disposal relief (BADR) from £1 million to £500,000 from April 2027 increases receipts by £0.3 billion in 2029-30."],
